// MASTER #5 — Comparison and evidence strength (sections 11, 17, 18, 19, 20, 42, 43, 72, 73).
//
// What this file refuses to do is as important as what it does.
//
// It computes NO p-value and NO confidence percentage. Section 18 is explicit,
// and the reason is not squeamishness about statistics: with two or three
// videos per arm, the assumptions behind any significance test are nowhere near
// satisfied, and "94% confident" would be a number generated by a procedure
// that does not apply. Named evidence states are less impressive and more
// honest.
//
// It also never picks the metric that happened to move. The primary metric was
// registered before results existed and it is the only one that decides
// anything (section 11). Secondary metrics explain; guardrails veto; neither
// promotes a loss into a win.
//
// "Indistinguishable" and "insufficient" are real outcomes, not failures to
// produce a result. A null result is information (section 42).

import type { SnapshotWindow } from "../../types.ts";
import {
  outcomeHasDirection,
  type ComparisonOutcome,
  type EvidenceStrength,
  type Experiment,
  type ValidityState,
} from "./model.ts";
import { lookupMetric, measuredValue, metricsAreComparable, type MetricReading } from "./metrics.ts";
import {
  assertOneObservationPerCreative,
  type PerformanceObservation,
} from "./observation.ts";
import type { IndependenceBreakdown } from "./assignment.ts";

// ---------------------------------------------------------------------------
// Sample accounting (section 19)
// ---------------------------------------------------------------------------

export interface SampleAccounting {
  readonly rawObservationCount: number;
  readonly uniqueCreativeCount: number;
  readonly independentUnitCount: number;
  readonly unitsPerVariant: ReadonlyMap<string, number>;
  readonly meetsMinimum: boolean;
  readonly explanation: string;
}

/**
 * Count what may honestly be called a sample.
 *
 * `independentUnitCount` is the only number that may be used as a sample size.
 * The other two are reported so the gap between them is visible: when raw
 * observations are five and independent units are two, someone is about to
 * claim five.
 */
export function accountSample(
  observations: readonly PerformanceObservation[],
  independence: IndependenceBreakdown,
  experiment: Experiment,
): SampleAccounting {
  assertOneObservationPerCreative(observations);

  const unitsPerVariant = new Map<string, number>();
  const creativesByVariant = new Map<string, Set<string>>();
  for (const observation of observations) {
    const set = creativesByVariant.get(observation.variantId) ?? new Set<string>();
    set.add(observation.creativeLineageId);
    creativesByVariant.set(observation.variantId, set);
  }
  for (const [variantId, lineages] of creativesByVariant) {
    unitsPerVariant.set(variantId, lineages.size);
  }

  const required = experiment.minimumEvidence.minimumIndependentUnitsPerVariant;
  const meetsMinimum =
    experiment.variants.every((variant) => (unitsPerVariant.get(variant.variantId) ?? 0) >= required);

  return {
    rawObservationCount: observations.length,
    uniqueCreativeCount: new Set(observations.map((observation) => observation.creativeId)).size,
    independentUnitCount: independence.independentUnitCount,
    unitsPerVariant,
    meetsMinimum,
    explanation:
      `${observations.length} observation(s) across ${new Set(observations.map((o) => o.creativeId)).size} creative(s) ` +
      `reduce to ${independence.independentUnitCount} independent unit(s). ` +
      `The design requires ${required} per variant; ` +
      (meetsMinimum ? "that is met." : "that is NOT met, so no variant may be declared a winner.") +
      " Windows, metrics and platform adaptations are never counted as separate samples.",
  };
}

// ---------------------------------------------------------------------------
// Metric comparison
// ---------------------------------------------------------------------------

export interface MetricComparison {
  readonly metricId: string;
  readonly window: SnapshotWindow;
  readonly controlReadings: readonly MetricReading[];
  readonly variantReadings: readonly MetricReading[];
  readonly controlMean: number | null;
  readonly variantMean: number | null;
  /** Relative difference, or null when either side has no measurement. */
  readonly relativeDifference: number | null;
  readonly outcome: ComparisonOutcome;
  readonly explanation: string;
}

/**
 * Below this relative difference, two small samples are treated as saying the
 * same thing.
 *
 * Not a significance threshold — there is no test here. It is an honesty
 * threshold: with a handful of videos, a 4% gap is indistinguishable from
 * noise, and reporting it as a direction would manufacture a finding. The
 * number is arguable and deliberately visible rather than buried.
 */
export const INDISTINGUISHABLE_RELATIVE_DIFFERENCE = 0.1;

function meanOf(readings: readonly MetricReading[]): number | null {
  const values = readings.map(measuredValue).filter((value): value is number => value !== null);
  if (values.length === 0) return null;
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}

/**
 * Compare one metric between control and variant.
 *
 * Every non-directional outcome is returned explicitly rather than being
 * smoothed into a weak direction. A missing measurement produces
 * `comparison-unavailable`, never a zero that would read as a catastrophic
 * loss.
 */
export function compareMetric(input: {
  readonly metricId: string;
  readonly window: SnapshotWindow;
  readonly controlObservations: readonly PerformanceObservation[];
  readonly variantObservations: readonly PerformanceObservation[];
  readonly validity: ValidityState;
}): MetricComparison {
  const { metricId, window } = input;

  const controlReadings = input.controlObservations.map(
    (observation) => observation.metrics.get(metricId) ?? { state: "not-collected" as const, reason: "Metric absent from the observation." },
  );
  const variantReadings = input.variantObservations.map(
    (observation) => observation.metrics.get(metricId) ?? { state: "not-collected" as const, reason: "Metric absent from the observation." },
  );

  const base = { metricId, window, controlReadings, variantReadings };

  // Platform mixing is refused before any arithmetic (section 57).
  const platforms = new Set([
    ...input.controlObservations.map((observation) => observation.platform),
    ...input.variantObservations.map((observation) => observation.platform),
  ]);
  if (platforms.size > 1) {
    return {
      ...base,
      controlMean: null,
      variantMean: null,
      relativeDifference: null,
      outcome: "comparison-invalid",
      explanation:
        `Observations span ${[...platforms].join(" and ")}. "${metricId}" is not the same measurement on different platforms, ` +
        "and no justified normalization exists, so the comparison is refused rather than averaged.",
    };
  }

  const windows = new Set([
    ...input.controlObservations.map((observation) => observation.window),
    ...input.variantObservations.map((observation) => observation.window),
  ]);
  if (windows.size > 1) {
    return {
      ...base,
      controlMean: null,
      variantMean: null,
      relativeDifference: null,
      outcome: "window-mismatch",
      explanation: `Observations mix the ${[...windows].sort().join(" and ")} windows, which compares elapsed time rather than creative.`,
    };
  }

  if (input.validity === "invalid") {
    return { ...base, controlMean: null, variantMean: null, relativeDifference: null, outcome: "comparison-invalid", explanation: "The comparison itself is invalid." };
  }

  if (input.controlObservations.length === 0 || input.variantObservations.length === 0) {
    return {
      ...base,
      controlMean: null,
      variantMean: null,
      relativeDifference: null,
      outcome: "insufficient-observations",
      explanation: "One side of the comparison has no observations at all, so there is nothing to compare.",
    };
  }

  const controlMean = meanOf(controlReadings);
  const variantMean = meanOf(variantReadings);

  if (controlMean === null || variantMean === null) {
    const missingSide = controlMean === null ? "control" : "variant";
    const states = [...new Set((controlMean === null ? controlReadings : variantReadings).map((reading) => reading.state))];
    return {
      ...base,
      controlMean,
      variantMean,
      relativeDifference: null,
      outcome: "comparison-unavailable",
      explanation:
        `The ${missingSide} side has no measured value for "${metricId}" (states: ${states.join(", ")}). ` +
        "An unmeasured metric is not zero, so no comparison is produced rather than a fabricated loss.",
    };
  }

  if (input.validity === "confounded") {
    return {
      ...base,
      controlMean,
      variantMean,
      relativeDifference: relativeDifferenceOf(controlMean, variantMean),
      outcome: "comparison-confounded",
      explanation:
        `The numbers are real (control ${controlMean}, variant ${variantMean}) but multiple dimensions changed, so the ` +
        "difference cannot be attributed to the intended variable.",
    };
  }

  const relativeDifference = relativeDifferenceOf(controlMean, variantMean);
  if (relativeDifference === null) {
    return { ...base, controlMean, variantMean, relativeDifference: null, outcome: "indistinguishable", explanation: "Both sides measured zero; there is no difference to report." };
  }

  if (Math.abs(relativeDifference) < INDISTINGUISHABLE_RELATIVE_DIFFERENCE) {
    return {
      ...base,
      controlMean,
      variantMean,
      relativeDifference,
      outcome: "indistinguishable",
      explanation:
        `Control ${controlMean} vs variant ${variantMean} — a ${(relativeDifference * 100).toFixed(1)}% difference, below the ` +
        `${INDISTINGUISHABLE_RELATIVE_DIFFERENCE * 100}% threshold at which a difference of this size can be told apart from noise ` +
        "at these sample sizes. This is a null result, which is a result.",
    };
  }

  const definition = lookupMetric(input.controlObservations[0].platform, metricId);
  const higherIsBetter = definition === null || definition.direction !== "lower-is-better";
  const variantWins = higherIsBetter ? variantMean > controlMean : variantMean < controlMean;

  return {
    ...base,
    controlMean,
    variantMean,
    relativeDifference,
    outcome: variantWins ? "variant-higher" : "control-higher",
    explanation:
      `Control ${controlMean} vs variant ${variantMean} on "${metricId}" at ${window} — ` +
      `a ${Math.abs(relativeDifference * 100).toFixed(1)}% difference favouring the ${variantWins ? "variant" : "control"}. ` +
      "This describes THIS comparison; it is not a general finding.",
  };
}

function relativeDifferenceOf(controlMean: number, variantMean: number): number | null {
  if (controlMean === 0) return variantMean === 0 ? null : 1;
  return (variantMean - controlMean) / Math.abs(controlMean);
}

// ---------------------------------------------------------------------------
// Guardrails (section 12)
// ---------------------------------------------------------------------------

export interface GuardrailResult {
  readonly guardrailId: string;
  readonly passed: boolean;
  readonly detail: string;
}

export interface GuardrailVerdict {
  readonly allPassed: boolean;
  readonly failures: readonly GuardrailResult[];
  readonly results: readonly GuardrailResult[];
  readonly explanation: string;
}

/**
 * Apply guardrails.
 *
 * A guardrail failure is absolute: it does not reduce a win, it cancels it.
 * Section 47 — a misleading variant that retains better has not won, it has
 * found a more efficient way to mislead.
 */
export function evaluateGuardrails(results: readonly GuardrailResult[]): GuardrailVerdict {
  const failures = results.filter((result) => !result.passed);
  return {
    allPassed: failures.length === 0,
    failures,
    results,
    explanation:
      failures.length === 0
        ? `All ${results.length} guardrail(s) passed.`
        : `${failures.length} guardrail(s) FAILED: ${failures.map((failure) => failure.guardrailId).join(", ")}. ` +
          "A guardrail failure overrides the performance result entirely. Performance never authorises lower integrity, " +
          "so this variant cannot be recommended however well it performed.",
  };
}

// ---------------------------------------------------------------------------
// Evidence strength (sections 18, 20, 78)
// ---------------------------------------------------------------------------

export interface EvidenceAssessment {
  readonly strength: EvidenceStrength;
  readonly reasons: readonly string[];
  readonly explanation: string;
}

/**
 * Judge how strong the evidence is, from validity, sample and replication.
 *
 * No arithmetic on confidence. The ceiling is set by the weakest input: a clean
 * experiment with one unit per arm is still anecdotal, because one pair of
 * videos is one pair of videos however carefully it was constructed.
 */
export function assessEvidence(input: {
  readonly validity: ValidityState;
  readonly sample: SampleAccounting;
  readonly outcome: ComparisonOutcome;
  readonly replicationCount: number;
  readonly conflictingReplications: number;
  readonly guardrails: GuardrailVerdict;
}): EvidenceAssessment {
  const reasons: string[] = [];

  if (!input.guardrails.allPassed) {
    return {
      strength: "insufficient",
      reasons: [input.guardrails.explanation],
      explanation: "A guardrail failed, so the performance result yields no usable evidence about the creative variable.",
    };
  }

  if (input.validity === "invalid") {
    return { strength: "insufficient", reasons: ["The comparison is invalid."], explanation: "Nothing can be learned from an invalid comparison." };
  }

  if (!outcomeHasDirection(input.outcome)) {
    if (input.outcome === "indistinguishable") {
      reasons.push("The variants were indistinguishable on the primary metric — a genuine null result, recorded rather than discarded.");
      return {
        strength: input.sample.meetsMinimum ? "directional" : "anecdotal",
        reasons,
        explanation:
          "A null result is evidence that changing this dimension may not matter much within this scope. It is not evidence " +
          "that it never matters anywhere.",
      };
    }
    return {
      strength: "insufficient",
      reasons: [`The comparison produced "${input.outcome}", which names no direction.`],
      explanation: "No direction was established, so there is nothing to be more or less confident about.",
    };
  }

  if (input.conflictingReplications > 0) {
    return {
      strength: "conflicting",
      reasons: [
        `${input.conflictingReplications} replication(s) point the other way. Conflicting evidence is its own state and is ` +
          "never averaged into a middle position: the disagreement is the finding.",
      ],
      explanation:
        "Experiments addressing this hypothesis disagree. The next step is a discriminating experiment that could explain " +
        "WHY they disagree, not a summary that hides it.",
    };
  }

  if (!input.sample.meetsMinimum) {
    reasons.push(input.sample.explanation);
    return {
      strength: "anecdotal",
      reasons,
      explanation:
        "A direction appeared, but below the declared minimum evidence. One interesting pair is a reason to look again, " +
        "not a reason to change how content is made.",
    };
  }

  if (input.validity === "observational-comparison") {
    reasons.push("This was an observational comparison rather than a controlled test.");
    return {
      strength: "directional",
      reasons,
      explanation: "Observational evidence can motivate a controlled experiment. It cannot substitute for one.",
    };
  }

  if (input.validity === "confounded") {
    reasons.push("Multiple dimensions changed, so the direction cannot be attributed to the intended variable.");
    return {
      strength: "anecdotal",
      reasons,
      explanation: "A real difference was observed between two creatives, but not evidence about the variable under test.",
    };
  }

  if (input.replicationCount === 0) {
    reasons.push("The result has not been replicated.");
    return {
      strength: "replication-needed",
      reasons,
      explanation:
        "A controlled result with adequate units and no guardrail failure. Exactly the position where replication is the " +
        "correct next step, and where treating it as a rule would be premature.",
    };
  }

  if (input.replicationCount >= 2 && input.validity === "clean-controlled") {
    reasons.push(`${input.replicationCount} independent replications agree, all cleanly controlled.`);
    return {
      strength: "strong-within-scope",
      reasons,
      explanation: "Reproduced more than once within one scope. Strong HERE; still says nothing about other platforms or topics.",
    };
  }

  reasons.push(`${input.replicationCount} replication(s) agree with the original direction.`);
  return {
    strength: "replicated",
    reasons,
    explanation: "Reproduced independently within this scope. Cautious reuse inside the same scope is defensible.",
  };
}

// ---------------------------------------------------------------------------
// Outliers (sections 72, 73)
// ---------------------------------------------------------------------------

export type OutlierState = "no-baseline" | "within-baseline" | "outlier-needs-replication";

export interface OutlierAssessment {
  readonly state: OutlierState;
  readonly explanation: string;
}

/**
 * Is this result extreme relative to the account's own recent baseline?
 *
 * There is no universal "viral" threshold here, and the word is not used as a
 * category (section 73). Extremity is relative to this account's own history,
 * and with no history the honest answer is that there is no baseline — not that
 * the result is normal.
 */
export function assessOutlier(
  value: number | null,
  baseline: readonly number[],
  baselineCapturedAt: string | null,
  now: Date,
): OutlierAssessment {
  if (value === null || baseline.length === 0) {
    return {
      state: "no-baseline",
      explanation:
        "No recent performance baseline exists for this account, so nothing can be called unusual. Without a baseline, " +
        "'this did well' has no referent.",
    };
  }

  if (baselineCapturedAt !== null) {
    const ageDays = (now.getTime() - Date.parse(baselineCapturedAt)) / 86_400_000;
    if (ageDays > 90) {
      return {
        state: "no-baseline",
        explanation:
          `The baseline is ${Math.round(ageDays)} days old. Platform distribution and audience composition drift, so a stale ` +
          "baseline cannot establish what is normal now.",
      };
    }
  }

  const mean = baseline.reduce((sum, entry) => sum + entry, 0) / baseline.length;
  if (mean === 0) return { state: "no-baseline", explanation: "The baseline mean is zero, so no relative comparison is meaningful." };

  const ratio = value / mean;
  if (ratio >= 3) {
    return {
      state: "outlier-needs-replication",
      explanation:
        `This result is ${ratio.toFixed(1)}x the recent baseline of ${mean.toFixed(1)}. It is flagged rather than dropped, and ` +
        "rather than universalised: one extreme result is the weakest possible basis for changing strategy, and novelty alone " +
        "can produce a spike that does not survive repetition.",
    };
  }

  return {
    state: "within-baseline",
    explanation: `This result is ${ratio.toFixed(1)}x the recent baseline of ${mean.toFixed(1)}, which is within the normal range for this account.`,
  };
}

// ---------------------------------------------------------------------------
// Cherry-picking protection (sections 11, 23)
// ---------------------------------------------------------------------------

export interface CherryPickFinding {
  readonly code: string;
  readonly message: string;
}

/**
 * Detect a decision being driven by something other than the primary metric.
 *
 * The specific move this catches: the primary metric says the variant lost or
 * tied, a secondary metric favours it, and the secondary becomes the headline.
 */
export function detectCherryPicking(
  experiment: Experiment,
  primary: MetricComparison,
  secondaries: readonly MetricComparison[],
  claimedWinnerVariantId: string | null,
  controlVariantId: string,
): readonly CherryPickFinding[] {
  const findings: CherryPickFinding[] = [];

  if (claimedWinnerVariantId === null) return findings;

  const primaryFavoursVariant = primary.outcome === "variant-higher";
  const primaryFavoursControl = primary.outcome === "control-higher";
  const claimedControl = claimedWinnerVariantId === controlVariantId;

  if (!outcomeHasDirection(primary.outcome)) {
    const favourableSecondary = secondaries.find((comparison) => outcomeHasDirection(comparison.outcome));
    findings.push({
      code: "winner-without-primary-direction",
      message:
        `A winner ("${claimedWinnerVariantId}") is claimed, but the primary metric "${experiment.primaryMetricId}" produced ` +
        `"${primary.outcome}", which names no direction.` +
        (favourableSecondary !== undefined
          ? ` The secondary metric "${favourableSecondary.metricId}" does show a direction — deciding on it would be exactly the ` +
            "cherry-pick the primary metric was registered in advance to prevent."
          : ""),
    });
    return findings;
  }

  if ((primaryFavoursVariant && claimedControl) || (primaryFavoursControl && !claimedControl)) {
    findings.push({
      code: "winner-contradicts-primary-metric",
      message:
        `The primary metric "${experiment.primaryMetricId}" favours the ${primaryFavoursVariant ? "variant" : "control"}, but ` +
        `"${claimedWinnerVariantId}" is claimed as the winner. The primary metric was chosen before results precisely so that ` +
        "this could not be revisited afterwards.",
    });
  }

  return findings;
}

/** Confirm a metric may be compared at all before any reading is taken. */
export function assertMetricComparable(
  control: readonly PerformanceObservation[],
  variant: readonly PerformanceObservation[],
  metricId: string,
): { readonly comparable: boolean; readonly reason: string } {
  if (control.length === 0 || variant.length === 0) {
    return { comparable: false, reason: "One side has no observations." };
  }
  return metricsAreComparable(
    { platform: control[0].platform, metricId },
    { platform: variant[0].platform, metricId },
  );
}
